```sqlite
SELECT S.Major, S.Fname, S.Lname FROM Student AS S LEFT OUTER JOIN Has_Pet AS HP ON S.StuID = HP.StuID LEFT OUTER JOIN Pets AS P ON HP.PetID = P.PetID WHERE P.PetType != 'cat';
```

```sqlite
SELECT PetType, AVG(pet_age), MAX(pet_age) FROM Pets GROUP BY PetType;
```

```sqlite
SELECT PetType, AVG(pet_age), MAX(pet_age) FROM Pets GROUP BY PetType;
```

```sqlite
SELECT DISTINCT T1.LName FROM Student AS T1 INNER JOIN Has_Pet AS T2 ON T1.StuID = T2.StuID INNER JOIN Pets AS T3 ON T2.PetID = T3.PetID WHERE T3.PetType = 'cat' AND T3.pet_age = 3;
```

```sqlite
SELECT Model FROM model_list ORDER BY Horsepower ASC LIMIT 1;
```

```sqlite
SELECT T2.Accelerate FROM cars_data AS T1 INNER JOIN car_names AS T2 ON T1.Id = T2.MakeId WHERE T2.Model = "Hornet Sportabout (sw)" AND T1.Horsepower = "234";
```

```sqlite
SELECT Model FROM model_list ORDER BY MPG DESC LIMIT 1;
```

```sqlite
SELECT T1.Cylinders FROM cars_data AS T1 JOIN car_names AS T2 ON T1.Id = T2.MakeId WHERE T2.Make = 'volvo' ORDER BY T1.Accelerate ASC LIMIT 1;
```

```sqlite
SELECT DISTINCT P.Paragraph_Text FROM Paragraphs P JOIN Documents D ON P.Document_ID = D.Document_ID WHERE P.Paragraph_Text LIKE '%Korea%';
```

```sqlite
SELECT D.Document_ID, D.Document_Name FROM Documents D JOIN (SELECT Document_ID, COUNT(*) AS ParagraphCount FROM Paragraphs GROUP BY Document_ID) P ON D.Document_ID = P.Document_ID WHERE P.ParagraphCount = (SELECT MAX(ParagraphCount) FROM (SELECT Document_ID, COUNT(*) AS ParagraphCount FROM Paragraphs GROUP BY Document_ID) AS P2);
```

```sqlite
SELECT v.ID, v.Name, v.Level_of_membership FROM visitor v JOIN (SELECT visitor_ID, SUM(Total_spent) AS total_spent FROM visit GROUP BY visitor_ID ORDER BY total_spent DESC LIMIT 1) AS most_spending ON v.ID = most_spending.visitor_ID;
```

```sqlite
SELECT p.first_name, p.country_code FROM players p JOIN rankings r ON p.player_id = r.player_id ORDER BY r.tours DESC LIMIT 1;
```

```sqlite
SELECT winner_name, winner_rank FROM matches WHERE round = 'Final' ORDER BY winner_age ASC LIMIT 3;
```

```sqlite
SELECT s.first_name, s.middle_name, s.last_name, COUNT(se.student_id) AS enrolment_count FROM Students s JOIN Student_Enrolment se ON s.student_id = se.student_id GROUP BY s.student_id ORDER BY enrolment_count DESC LIMIT 1;
```

```sqlite
SELECT p.Name FROM poker_player p ORDER BY p.Final_Table_Made DESC;
```

```sqlite
SELECT COUNT(DISTINCT Language) FROM countrylanguage WHERE CountryCode = 'ARA';
```

```sqlite
SELECT COUNT(DISTINCT Language) FROM countrylanguage WHERE CountryCode = 'AF' AND IsOfficial = 'T';
```

```sqlite
SELECT COUNT(*) FROM countrylanguage WHERE CountryCode = (SELECT Code FROM country WHERE Name = 'Afghanistan') AND IsOfficial = 'T';
```

```sqlite
SELECT T1.Name FROM country AS T1 INNER JOIN countrylanguage AS T2 ON T1.Code = T2.CountryCode GROUP BY T1.Code, T2.Language HAVING COUNT(T2.Language) = (SELECT MAX(LanguageCount) FROM (SELECT COUNT(Language) AS LanguageCount FROM countrylanguage GROUP BY CountryCode) AS Subquery);
```

```sqlite
SELECT Name, Population, LifeExpectancy FROM country WHERE Continent = 'Asia' ORDER BY SurfaceArea DESC LIMIT 1;
```

```sqlite
SELECT AVG(LifeExpectancy) FROM countrylanguage WHERE Language = 'English' AND IsOfficial = 'T';
```

```sqlite
SELECT Name FROM country WHERE Continent = 'Europe' AND SurfaceArea < (SELECT MAX(SurfaceArea) FROM country WHERE Continent = 'Europe');
```

```sqlite
SELECT Name, IndepYear, SurfaceArea FROM country ORDER BY Population ASC LIMIT 1;
```

```sqlite
SELECT AVG(CAST(REPLACE(age, '-', '') AS REAL)) FROM Dogs WHERE dog_id IN (SELECT dog_id FROM Treatments);
```

```sqlite
SELECT DISTINCT o.first_name, o.last_name, o.email_address FROM Owners o JOIN Dogs d ON o.owner_id = d.owner_id WHERE o.state LIKE '%North%';
```
